import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CAUU6m5Y.js";const u=JSON.parse('{"title":"Technical Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"11-glossary.md","filePath":"11-glossary.md"}'),o={name:"11-glossary.md"};function s(r,e,l,c,d,g){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="technical-glossary" tabindex="-1">Technical Glossary <a class="header-anchor" href="#technical-glossary" aria-label="Permalink to &quot;Technical Glossary&quot;">​</a></h1><ul><li><strong>Atomic Conditional Update</strong>: A single SQL statement (<code>UPDATE ... WHERE condition</code>) that evaluates availability and applies decrements atomically inside the database engine without holding open application-level locks.</li><li><strong>Conservation Invariant</strong>: The mathematical law $Available + Reserved + Sold == Total Allocated$ that must evaluate to true across all points in time.</li><li><strong>Fencing Token</strong>: A monotonically increasing integer issued by a distributed lock manager to detect and reject stale writes from paused or partitioned clients.</li><li><strong>Idempotency Key</strong>: A unique client-supplied token (UUID) ensuring an operation (e.g. payment or order creation) is executed exactly once even when retried multiple times.</li><li><strong>Optimistic Concurrency Control (OCC)</strong>: A concurrency management method that assumes conflicts are rare, checking a record&#39;s version column at commit time and retrying if conflicts occur.</li><li><strong>Pessimistic Locking</strong>: Locking a database row (<code>SELECT FOR UPDATE</code>) to prevent any other transaction from reading or writing until the lock is released.</li><li><strong>Token Bucket</strong>: A rate-limiting algorithm where tokens refill at a steady rate and burst requests consume tokens up to bucket capacity.</li><li><strong>Virtual Waiting Room</strong>: A FIFO queue admission gatekeeper that throttles traffic surges during sale openings, admitting users in metered batches.</li></ul>',2)])])}const p=t(o,[["render",s]]);export{u as __pageData,p as default};
